using HDFCSmartGateway.Models;using HDFCSmartGateway.Services;using Newtonsoft.Json.Linq;using System;using System.Threading.Tasks;using System.Web.Mvc;namespace HDFCSmartGateway.Controllers { public class PaymentController:Controller {readonly HdfcSettings s=new HdfcSettings();HdfcPaymentService Api{get{return new HdfcPaymentService(s);}}[HttpGet]public ActionResult Create(){return View(new CreatePaymentModel{Amount=10m});}[HttpPost,ValidateAntiForgeryToken]public async Task<ActionResult>Create(CreatePaymentModel m){if(!ModelState.IsValid)return View(m);var e=s.Validate();if(e!=null){ModelState.AddModelError("",e);return View(m);}if(String.IsNullOrWhiteSpace(m.CustomerEmail)&&String.IsNullOrWhiteSpace(m.CustomerPhone)){ModelState.AddModelError("","Provide email or phone.");return View(m);}try{var raw=await Api.CreateAsync(m);var j=JObject.Parse(raw);ViewBag.Raw=raw;ViewBag.OrderId=m.OrderId;ViewBag.PaymentUrl=(string)(j.SelectToken("payment_links.web")??j.SelectToken("payment_url"));return View("Result");}catch(Exception x){ModelState.AddModelError("",x.Message);return View(m);}}[HttpGet]public ActionResult Return(){ViewBag.OrderId=Request.QueryString["order_id"];ViewBag.Status=Request.QueryString["status"];return View();}[HttpGet]public ActionResult Status(){return View(new StatusModel());}[HttpPost,ValidateAntiForgeryToken]public async Task<ActionResult>Status(StatusModel m){if(!ModelState.IsValid)return View(m);var e=s.Validate();if(e!=null){ModelState.AddModelError("",e);return View(m);}try{ViewBag.OrderId=m.OrderId;ViewBag.Raw=await Api.StatusAsync(m.OrderId,m.CustomerId);return View("StatusResult");}catch(Exception x){ModelState.AddModelError("",x.Message);return View(m);}}} }